 "content": "def transform(grid):
    out = [row[:] for row in grid]
    # Find the enclosing colored rectangle and build alternating concentric
    # borders inside it, preserving a 3x3 empty center.
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    if not points:
        return out
    r0 = min(r for r, _ in points)
    r1 = max(r for r, _ in points)
    c0 = min(c for _, c in points)
    c1 = max(c for _, c in points)
    inset = 1
    color = 2
    while r0 + inset + 1 < r1 - inset and c0 + inset + 1 < c1 - inset:
        # Leave the final 3x3 central area blank.
        if (r1 - r0 + 1 - 2 * inset) <= 3 or (c1 - c0 + 1 - 2 * inset) <= 3:
            break
        top, bottom = r0 + inset, r1 - inset
        left, right = c0 + inset, c1 - inset
        for c in range(left, right + 1):
            out[top][c] = color
            out[bottom][c] = color
        for r in range(top, bottom + 1):
            out[r][left] = color
            out[r][right] = color
        color = 5 if color == 2 else 2
        inset += 1
    return out

def _self_test():
    demo = [[0] * 13 for _ in range(13)]
